        assertEquals("Fackel", g.getName(), "getName() muss den Namen des Gegenstands liefern");
        assertEquals(5, g.getWert(), "getWert() muss den Wert in Gold liefern");
    }

    @Test
    public void basis_gegenstandBeschreibung() {
        Gegenstand g = new Gegenstand("Fackel", 5);
        assertEquals("Fackel (5 Gold)", g.beschreibung(), "beschreibung() muss genau so aussehen: Fackel (5 Gold)");
    }

    @Test
    public void basis_inventarAnfangsLeer() {
        Held h = new Held("Aria");
        assertEquals(0, h.getAnzahl(), "Ein neuer Held hat 0 Gegenstaende im Inventar");
    }

    @Test
    public void basis_aufnehmenEinGegenstand() {
        Held h = new Held("Aria");
        boolean ok = h.aufnehmen(new Gegenstand("Fackel", 5));
        assertTrue(ok, "aufnehmen muss true liefern, wenn noch Platz ist");
        assertEquals(1, h.getAnzahl(), "Nach einem aufnehmen muss getAnzahl() 1 liefern");
    }

    @Test
    public void erweiterung_aufnehmenBisVoll() {
        Held h = new Held("Aria");
        for (int i = 1; i <= 5; i++) {
            boolean ok = h.aufnehmen(new Gegenstand("Stein " + i, 1));
            assertTrue(ok, "Gegenstand Nr. " + i + " muss noch ins Inventar passen (Platz fuer 5)");
        }
        assertEquals(5, h.getAnzahl(), "Nach 5 aufnehmen muss getAnzahl() 5 liefern");
    }

    @Test
    public void erweiterung_aufnehmenWennVoll() {
        Held h = new Held("Aria");
        for (int i = 1; i <= 5; i++) {
            h.aufnehmen(new Gegenstand("Stein " + i, 1));
        }
        boolean ok = h.aufnehmen(new Gegenstand("Stein 6", 1));
        assertFalse(ok, "Das Inventar ist voll: aufnehmen muss false liefern");
        assertEquals(5, h.getAnzahl(), "Bei vollem Inventar darf anzahl nicht weiter steigen");
    }

    @Test
    public void erweiterung_aufnehmenNull() {
        Held h = new Held("Aria");
        boolean ok = h.aufnehmen(null);
        assertFalse(ok, "aufnehmen(null) muss false liefern - null ist kein Gegenstand");
        assertEquals(0, h.getAnzahl(), "aufnehmen(null) darf anzahl nicht erhoehen");
    }

    @Test
    public void erweiterung_gesamtWert() {
        Held h = new Held("Aria");
        h.aufnehmen(new Gegenstand("Fackel", 5));
        h.aufnehmen(new Gegenstand("Krone", 50));
        h.aufnehmen(new Gegenstand("Seil", 20));
        assertEquals(75, h.gesamtWert(), "gesamtWert: 5 + 50 + 20 = 75");
    }

    @Test
    public void erweiterung_gesamtWertLeer() {
        Held h = new Held("Aria");
        assertEquals(0, h.gesamtWert(), "Der Gesamtwert eines leeren Inventars ist 0");
    }

    @Test
    public void erweiterung_enthaelt() {
        Held h = new Held("Aria");
        h.aufnehmen(new Gegenstand("Fackel", 5));
        h.aufnehmen(new Gegenstand("Seil", 20));
        assertTrue(h.enthaelt("Fackel"), "Die Fackel ist im Inventar: enthaelt muss true liefern");
        assertTrue(h.enthaelt("Seil"), "Das Seil (letzter Gegenstand) ist im Inventar: enthaelt muss true liefern");
        assertFalse(h.enthaelt("Schwert"), "Ein Schwert ist nicht im Inventar: enthaelt muss false liefern");
    }

    @Test
    public void erweiterung_enthaeltLeer() {
        Held h = new Held("Aria");
        assertFalse(h.enthaelt("Fackel"), "Im leeren Inventar ist nichts enthalten - Vorsicht vor null-Eintraegen!");
    }

    @Test
    public void experte_wertvollsterLeer() {
        Held h = new Held("Aria");
        assertTrue(h.wertvollsterGegenstand() == null, "Bei leerem Inventar muss wertvollsterGegenstand() null liefern");
    }

    @Test
    public void experte_wertvollsterNormal() {
        Held h = new Held("Aria");
        Gegenstand krone = new Gegenstand("Krone", 50);
        h.aufnehmen(new Gegenstand("Fackel", 5));
        h.aufnehmen(krone);
        h.aufnehmen(new Gegenstand("Seil", 20));
        assertTrue(h.wertvollsterGegenstand() == krone, "Die Krone (50 Gold) ist der wertvollste Gegenstand");
    }

    @Test
    public void experte_wertvollsterAmAnfangUndAmEnde() {
        Held h = new Held("Aria");
        Gegenstand krone = new Gegenstand("Krone", 50);
        h.aufnehmen(krone);
        h.aufnehmen(new Gegenstand("Fackel", 5));
        assertTrue(h.wertvollsterGegenstand() == krone, "Die Krone steht ganz vorne und ist trotzdem der wertvollste Gegenstand");
        Gegenstand juwel = new Gegenstand("Juwel", 80);
        h.aufnehmen(juwel);
        assertTrue(h.wertvollsterGegenstand() == juwel, "Das Juwel (80 Gold) steht ganz hinten und ist jetzt der wertvollste");
    }

    @Test
    public void experte_wertvollsterGleichstand() {
        Held h = new Held("Aria");
        Gegenstand erste = new Gegenstand("Krone", 50);
        Gegenstand zweite = new Gegenstand("Zepter", 50);
        h.aufnehmen(new Gegenstand("Fackel", 5));
        h.aufnehmen(erste);
        h.aufnehmen(zweite);
        assertTrue(h.wertvollsterGegenstand() == erste, "Bei Gleichstand muss der ERSTE Gegenstand geliefert werden (Krone, nicht Zepter)");
    }

    @Test
    public void experte_enthaeltMitEquals() {
        Held h = new Held("Aria");
        h.aufnehmen(new Gegenstand("Fackel", 5));
        String teil = "Fa";
        String gesucht = teil + "ckel";
        assertTrue(h.enthaelt(gesucht), "enthaelt muss Zeichenketten mit equals vergleichen, nicht mit ==");
    }

    @Test
    public void experte_enthaeltNurExakterName() {
        Held h = new Held("Aria");
        h.aufnehmen(new Gegenstand("Fackel", 5));
        assertFalse(h.enthaelt("Fack"), "Gesucht ist der exakte Name: 'Fack' ist nicht 'Fackel' (equals statt contains)");
        assertFalse(h.enthaelt("fackel"), "Gross- und Kleinschreibung zaehlt: 'fackel' ist nicht 'Fackel'");
        assertFalse(h.enthaelt(""), "Die leere Zeichenkette ist kein Gegenstandsname");
    }

    @Test
    public void experte_gesamtWertBeiVollemInventar() {
        Held h = new Held("Aria");
        for (int i = 1; i <= 6; i++) {
            h.aufnehmen(new Gegenstand("Muenze " + i, 10));
        }
        assertEquals(50, h.gesamtWert(), "Nur 5 Muenzen passen ins Inventar: gesamtWert muss 50 sein, nicht 60");
    }

    @Test
    public void experte_inventarMitZweitemKonstruktor() {
        Held h = new Held("Brann", 150, 14);
        boolean ok = h.aufnehmen(new Gegenstand("Fackel", 5));
        assertTrue(ok, "Auch ein Held aus dem zweiten Konstruktor braucht ein Inventar (Laenge 5)");
        assertEquals(1, h.getAnzahl(), "Auch beim zweiten Konstruktor muss aufnehmen anzahl erhoehen");
        assertEquals(5, h.gesamtWert(), "Auch beim zweiten Konstruktor muss gesamtWert funktionieren");
    }
}


